      INTEGER FUNCTION VARST(JV)CC     FIND VARY CODE FOR PARTICULAR PARAMETERCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM17B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'NELMS.CIN'C      INTEGER         CDBV      EXTERNAL        IDATAC      VARST = 0      NMAX = NELMS(TYPE)C      IF (TYPE .EQ. 6 .OR. TYPE .EQ. 37) GO TO 80      IF (TYPE .EQ. 13) THEN        CDBV = INT(DATA(I+1))        IF (CDBV .EQ. 9) GO TO 40      ENDIF      IF (TYPE .EQ. 14) THEN        IF (DATA(I+30) .NE. 0.0) NMAX = 29        IF (DATA(I+8) .NE. 0.0) NMAX = 7      ENDIFC      IF (JV .GT. NMAX) GO TO 100      IPARM = IPTOJ(JV)      IF (IPARM .EQ. 0) GO TO 100      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 50      IF (TYPE .EQ. 42) GO TO 55      IADR = I + IPARM   10 NVARY = TIE(IADR)      IF (NVARY .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 10      ENDIF      VARST = NVARY      GO TO 900C   40 VARST = JV      GO TO 900C   50 IF (TYPEC .EQ. 2) THEN        IF (BEFORE) THEN          IF (JV .EQ. NE1 .OR. JV .EQ. NH1) GO TO 60          IF ((JV .EQ. NBV .OR. JV .EQ. NANG) .AND. IPTOJ(NE1) .EQ. 0)     1         GO TO 60        ELSE          IF (JV .EQ. NE2 .OR. JV .EQ. NH2) GO TO 60          IF ((JV .EQ. NBV .OR. JV .EQ. NANG) .AND. IPTOJ(NE2) .EQ. 0)     1         GO TO 60        ENDIF        IE1 = IPTOJ(NE1)        IE2 = IPTOJ(NE2)        IF (TYPE .EQ. 28 .AND. ((BEFORE .AND. IE1 .EQ. 0)     1      .OR. (.NOT. BEFORE .AND. IE2 .EQ. 0))) THEN          IF (JV .EQ. NL .OR. JV .EQ. NBV .OR. JV .EQ. NRHO     1        .OR. JV .EQ. NANG) GO TO 60        ENDIF        IF (JV .EQ. NHGAP .OR. JV .EQ. NFINT) GO TO 60      ELSE IF (TYPEC .EQ. 4) THEN        IF ((JV .GE. NL .AND. JV .LE. NK1P)     1       .OR. (JV .GE. NBDB .AND. JV .LE. NK2P)     2       .OR. JV .EQ. NGAM .OR. JV .EQ. NK3     3       .OR. (JV .EQ. NTILT .AND. REFER)) GO TO 60      ELSE IF (TYPEC .EQ. 20) THEN        IF (JV .EQ. NTILT) GO TO 60      ENDIF      VARST = 0      GO TO 900C   55 IF (TYPEC .EQ. 35) THEN        IF (JV .EQ. 1 .OR. JV .EQ. 2 .OR. JV .EQ. 3) GO TO 60      ELSE IF (TYPEC .EQ. 20) THEN        IF (JV .EQ. 2 .OR. JV .EQ. 3) GO TO 60      ENDIF      VARST = 0      GO TO 900C   60 IF (IPARM .EQ. 0) GO TO 100      IADR = I + IPARM   65 NVARY = TIE(IADR)      IF (NVARY .EQ. 100) THEN        IADR = IDATA(IADR)        GO TO 65      ENDIF      VARST = NVARY      GO TO 900C   80 IF (RORC .GT. 0) THEN        IADR = I + IPTOJB(4)        NMISV = IDATA(IADR+NAL)      ELSE        NMISV = NIM(1,NAL)      ENDIF      IMIS = ISTOR(NMISV)      NVARY = TIE(IMIS + JV)      VARST = NVARY      GO TO 900C  100 IF (TYPEC .EQ. 4) GO TO 200      IF (TYPE .EQ. 2) GO TO 150      VARST = 0      GO TO 900C  150 IF (JV .EQ. 5) GO TO 180      IF (JV .EQ. 4) GO TO 160      GO TO 900C  160 IF (BEFORE) THEN        VARST = VARS(1)      ELSE        VARST = VARS(2)      ENDIF      GO TO 900C  180 NBVARY = TIE(IBVARY)      VARST = NBVARY      GO TO 900C  200 IF (JV .EQ. NRMPS) VARST = VARS(3)      IF (JV .EQ. NRNMS) VARST = VARS(4)      IF (JV .EQ. NVR) VARST = VARS(5)      IF (JV .EQ. NNP) VARST = VARS(6)      IF (JV .EQ. NBDB) VARST = VARS(7)      IF (JV .EQ. NBDBP) VARST = VARS(8)      IF (JV .EQ. NGAM) VARST = VARS(9)C  900 RETURN      END